#!/bin/sh
R=$(git -C "$(dirname "$0")" rev-parse --show-toplevel 2>/dev/null) && [ -x "$R/.venv/bin/python3" ] && PATH="$R/.venv/bin:$PATH"; export LC_ALL=en_US.UTF-8   # pin repo Python (3.12) and locale (glob order): page hashes depend on both
# Assemble ../index.html from parts/.
# HTML: 01_head, 02_css, 10_header, 20_read_a, 20_read_b, 20_read_c (Reading tab, with the former Dyna and Self-play labs inline), 39_tab_more (Further reading).
# JS: every *.js in parts/ in file-name order (20_js_mb_data.js is generated by mk_data.py), each in its own <script>, 99_js_tabs.js (the tab wiring) last.
# Links are written {{text|url}} (url may be n:<notion id>, or #t-<tab> for a link to a tab).
cd "$(dirname "$0")"
{ cat parts/01_head.html parts/02_css.html parts/10_header.html parts/20_read_a.html parts/20_read_b.html parts/20_read_c.html parts/39_tab_more.html
  echo '<div id="jsErr" hidden style="margin:12px 0;padding:10px 12px;border:1px solid #c2703a;border-radius:8px;font:13px/1.5 ui-monospace,Menlo,monospace;white-space:pre-wrap"></div>'
  cat parts/05z_errbox.js.html
  for f in parts/*.js; do [ "$(basename $f)" = 99_js_tabs.js ] && continue; echo "<script>/* $(basename $f) */"; cat "$f"; echo '</script>'; done
  echo "<script>/* 99_js_tabs.js */"; cat parts/99_js_tabs.js; echo '</script>'
  echo '</div></body></html>'; } | perl -CSD -pe '
s/\{\{([^|{}]+)\|([^{}]+)\}\}/my($t,$u)=($1,$2);if($u=~m{^#(t-[\w-]+)$}){"<a href=\"#\" data-tab=\"$1\">$t<\/a>"}else{$u=~s{^n:}{https:\/\/app.notion.com\/p\/};"<a href=\"$u\" target=\"_blank\" rel=\"noopener noreferrer\">$t<\/a>"}/ge;
' > ../index.html
# Reading time estimate (static text only, closed <details> apart). The header states the figure html_utils/audit_pages.mjs measures on the rendered page (it also counts script-written captions); update it by hand when the text changes.
python3 - <<'PY'
import re
s=open('../index.html').read()
a=s.index('id="t-read"');b=s.index('id="t-more"')
t=re.sub(r'<script.*?</script>|<style.*?</style>','',s[a:b],flags=re.S)
det=' '.join(re.findall(r'<details[^>]*>(.*?)</details>',t,flags=re.S))
core=re.sub(r'<details[^>]*>.*?</details>',' ',t,flags=re.S)
w=lambda x:len(re.sub(r'<[^>]+>',' ',x).split())
m,d=round(w(core)/230),round(w(det)/230)
open('../index.html','w').write(s.replace('RT_MIN',str(m)).replace('RT_DET',str(d)))
print('reading words',w(core),'minutes',m,'| closed details words',w(det),'minutes',d)
PY
if grep -q '{{' ../index.html; then echo "unexpanded link"; grep -o '{{[^}]*}}' ../index.html | head; fi
if grep -q '—' ../index.html; then echo "EM DASH FOUND"; grep -n -o '.\{30\}—.\{30\}' ../index.html | head; fi
wc -c ../index.html
